import pandas as pd


def _is_diff(a, b):
    """NULL-aware inequality: NULL vs NULL -> not different; NULL vs non-NULL -> different."""
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def _get_input(inputs: dict, name: str) -> pd.DataFrame:
    # Case-insensitive / flexible lookup for input relation names.
    if name in inputs:
        return inputs[name]
    lname = name.lower()
    for k, v in inputs.items():
        if k.lower() == lname:
            return v
    raise KeyError(name)


def run(inputs: dict) -> dict:
    dim_acct = _get_input(inputs, "DIM_ACCT").copy()
    stg_acct = _get_input(inputs, "STG_ACCT").copy()

    # Ensure expected columns exist
    dim_cols = ["acct_id", "email", "tier", "eff_start_date", "eff_end_date", "is_current"]
    for c in dim_cols:
        if c not in dim_acct.columns:
            dim_acct[c] = None
    dim_acct = dim_acct[dim_cols]

    stg_cols = ["acct_id", "email", "tier", "update_date"]
    for c in stg_cols:
        if c not in stg_acct.columns:
            stg_acct[c] = None
    stg_acct = stg_acct[stg_cols]

    # ---- Step 1: Dedup STG_ACCT to latest per acct_id by update_date,
    #      ties broken by greater (email, tier) lexicographic pair. ----
    if len(stg_acct) > 0:
        stg_sorted = stg_acct.sort_values(
            by=["acct_id", "update_date", "email", "tier"],
            ascending=[True, True, True, True],
            na_position="last",
            kind="mergesort",
        )
        stg_dedup = stg_sorted.groupby("acct_id", as_index=False, sort=False).tail(1)
    else:
        stg_dedup = stg_acct.copy()

    # ---- Step 2: process staged records against current dim rows ----
    rows = dim_acct.to_dict("records")

    def get_current_idx(acct_id):
        for i, r in enumerate(rows):
            if r["acct_id"] == acct_id and r["is_current"] == 1:
                return i
        return None

    for s in stg_dedup.itertuples(index=False):
        acct_id = s.acct_id
        s_email = s.email
        s_tier = s.tier
        s_update_date = s.update_date

        idx = get_current_idx(acct_id)

        if idx is None:
            # No current row exists: insert new current version.
            new_row = {
                "acct_id": acct_id,
                "email": s_email,
                "tier": s_tier,
                "eff_start_date": s_update_date,
                "eff_end_date": None,
                "is_current": 1,
            }
            rows.append(new_row)
        else:
            c = rows[idx]
            old_email = c["email"]
            old_tier = c["tier"]

            tier_changed = _is_diff(old_tier, s_tier)

            if tier_changed:
                # Expire the current row and insert a new current version.
                rows[idx]["eff_end_date"] = s_update_date
                rows[idx]["is_current"] = 0

                new_row = {
                    "acct_id": acct_id,
                    "email": s_email,
                    "tier": s_tier,
                    "eff_start_date": s_update_date,
                    "eff_end_date": None,
                    "is_current": 1,
                }
                rows.append(new_row)

            email_changed = _is_diff(old_email, s_email)

            if email_changed:
                # Retro-overwrite email across ALL rows (history + current,
                # including any just-inserted new version) for this acct_id.
                for r in rows:
                    if r["acct_id"] == acct_id:
                        r["email"] = s_email

    out = pd.DataFrame(rows, columns=dim_cols)

    return {"dim_acct_out": out}
